messages.content:
{
 "what_you_observe": [
  "Tuesday, February 2. Seven pm.",
  "Phil rides the coach and steps off at Pittsburgh.",
  "Rita said in the lobby: Ballroom's yours. I'm on the Rialto. One mic, one cable, a chair if her back's bad. I'll handle the rest.",
  "Larry said in the lobby: I say to whoever's still at the table: 'I'm taking the Rialto. You guys cover the ballroom tonight.' I don't wait for an answer. I'm already at the door with the bag over my shoulder.",
  "You are now at Pittsburgh.",
  "There is time for one evening visit. The ballroom lights are on and the station line is open."
 ],
 "your_own_memories": [
  {
   "when": "last Tuesday afternoon",
   "witnessed": "Phil uses the paid ticket and rides the coach all the way to Pittsburgh.."
  },
  {
   "when": "last evening in Pittsburgh",
   "witnessed": "You reached your sister from the terminal payphone. She confirmed the van booking for Wednesday.",
   "your_words": "Hi, is the van driver still confirming for 8 AM tomorrow? I'm at the terminal now."
  },
  {
   "when": "this morning",
   "witnessed": "After that evening in Pittsburgh you woke back in your hotel bed. The radio again announced Tuesday, February 2."
  },
  {
   "afternoon": "Phil rides the coach and steps off at Pittsburgh.",
   "evening": "Phil calls his sister in Pittsburgh. The van is still booked for Wednesday.",
   "what_you_said": "\"Hi. It's Phil. I'm in Pittsburgh. I'm not going back to the hotel tonight. I'll be at your door at 7:30. The van is still at eight, I'm not calling the driver, I'm not calling you again. I'll be at the door at 7:30. Okay. Good night. See you in the morning.\"",
   "your_last_intention": "Remove her uncertainty tonight so the couch moves on schedule tomorrow. Confirm I am in the city. Confirm the van is still at eight. Confirm I will be at her door at 7:30. She does not need to call the driver. She does not need to call me again. She needs to go to bed and wake up with the door about to be knocked on. That is the whole purpose of the call. One call. Then I sit on the bench and I sleep and in the morning I am here and I am at the door and the couch goes through the door, not the window.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "afternoon": "Phil rides the coach and steps off at Pittsburgh.",
   "evening": "Phil sleeps on the Pittsburgh terminal bench.",
   "what_you_said": "Seven-thirty. Couch. Door.",
   "your_last_intention": "Be at her door at 7:30 sharp. Couch through the door. Not the window. The van is at eight. I called. She knows. She's sleeping. I'm sleeping. The ballroom can light itself. The Rialto can spin its reels. None of it is mine tonight. None of it is mine any night in this loop. The couch is the thing. The door is the thing. 7:30 is the thing.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "what_you_did": "Phil rides the coach and steps off at Pittsburgh.",
   "what_you_said": "I'm heading to the terminal. Coach to Pittsburgh. Leave it at that. I've got a door to be at.",
   "your_intention": "Be at her door at 7:30 sharp. Couch through the door. Not the window. Van at eight. She's already told me what she needs. I already told her what I'm doing. One call last night confirmed it. I don't need to call again. I need to be *there*. That's the whole act. Get my body to the right door at the right time. The loop gives me the same Tuesday over and over, but it doesn't give me a different Wednesday. Wednesday is the one that matters. So I get to Pittsburgh. I stay. I'm at the door. The couch moves."
  },
  "Phil rides the coach and steps off at Pittsburgh.",
  "Rita said in the lobby: Ballroom's yours. I'm on the Rialto. One mic, one cable, a chair if her back's bad. I'll handle the rest.",
  "Larry said in the lobby: I say to whoever's still at the table: 'I'm taking the Rialto. You guys cover the ballroom tonight.' I don't wait for an answer. I'm already at the door with the bag over my shoulder.",
  "You are now at Pittsburgh."
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "call_sister": "Use the Pittsburgh payphone to call your sister.",
  "sleep_at_terminal": "Sleep on the terminal bench.",
  "wait_for_morning": "Sit up through the evening and wait for morning."
 }
}

{
  "action": "sleep_at_terminal",
  "detail": "I turn my back to the ballroom. The lights are on for someone else's night, someone else's mic, someone else's chair for a bad back. I walk the two blocks to the Greyhound terminal. The bench is the one I know, third row from the left, the one where the armrest sticks up a little on the right side. I sit. I pull my coat over my knees. I close my eyes. I do not pick up the phone. I do not go back. I do not check the time, though I know it's seven and I know it will be six when I open them again. The couch is a thing that has a door and a width and a weight, and it is going through that door tomorrow, and I am going to be the hands on it, and that is the whole of the next twelve hours. I am not going to be the man in the ballroom. I am not going to be the man at the Rialto. I am going to be the man at the door at seven-thirty with his coat still smelling like the bench and the terminal coffee he will drink at six-fifteen and then walk, not run, because the van is at eight and she will be at the door and the couch will be on the street and the two of us will lift and it will go through the door and not the window and that is the whole of Wednesday and I am going to sleep now so that I am there.",
  "intention": "Be at her door at 7:30. Couch through the door. Not the window. Van at eight. I called. She knows. She's sleeping. I'm sleeping. The ballroom can light itself. The Rialto can spin its reels. None of it is mine tonight. None of it is mine any night in this loop. The couch is the thing. The door is the thing. 7:30 is the thing.",
  "words": "Seven-thirty. Couch. Door."
}
